// scripts/rdt.mjs writes, plus its own wall time and peak RSS. It reads each file on its own with its default
// resolver and importer, as Storybook does, so it knows nothing about types declared in other files.
//
// Usage: node scripts/rdg.mjs <file-list> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { pathToFileURL, fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/validate/package.json', import.meta.url)))
const { parse } = await import(pathToFileURL(require.resolve('react-docgen')).href)

const [listFile, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdg.mjs <file-list> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const components = []
let failed = 0
// react-docgen-typescript on one corpus (scripts/weekly.py): every component's props with their declaring file, plus
// RDT's own wall time and peak RSS. RDT comes from apps/validate, with the options its harness uses.
//
// Usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/validate/package.json', import.meta.url)))
const { withCustomConfig } = require('react-docgen-typescript')

const [listFile, tsconfig, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const start = performance.now()
const parser = withCustomConfig(tsconfig, {
  shouldExtractLiteralValuesFromEnum: true,
    },
  })
  if (!values.corpora) throw new Error('--corpora <dir holding the cloned repositories> is required')
  const options = {
    corpora: resolve(values.corpora),
    limit: values.limit ? Number(values.limit) : Infinity,
    sample: values.sample ? Number(values.sample) : 100,
    files: values.files,
    // The addon build to measure; another build of the package runs the same stories for a before/after.
    dist: resolve(values.dist ?? join(here, '../dist')),
    typescript: resolve(
      values.typescript ?? join(here, '../../../apps/validate/node_modules/typescript/lib/typescript.js'),
    ),
    tsconfig: values.tsconfig,
  }

  if (values.child) {
    const result =
      values.child === 'session'
        ? await runSession(values.variant, values.corpus, options)
        : await runStories(values.variant, values.corpus, options)
        with:
          toolchain: ${{ steps.rust.outputs.version }}
      - uses: taiki-e/install-action@8cca0918f8471c33515202b73f56ab27f2bed283 # v2.87.29
        with:
          tool: just,cargo-nextest
      # The cli config tests spawn `node --import=tsx/esm`, and tsx is a devDependency of apps/validate.
      - uses: moonrepo/setup-toolchain@261c62cb5b0f580c7be7c8cd0f023a2e96756095 # v0.6.4
        with:
          auto-install: true
      - uses: orin-dx/actions/setup-pnpm-cache@2521888266780dabc7f5fd4c32b02d6ab82849db # v1.1
      - run: pnpm install --frozen-lockfile
      - run: just test-rust

  test-ts:
    name: Test / TypeScript / Node ${{ matrix.node }}
    runs-on: ubuntu-latest
      # The corpora's own package managers run under Node 24: Yarn 4.18, which Mantine and React Spectrum pin, crashes
      # under the repository's Node 26 ("Dynamic require of "util" is not supported"). This step comes before the
      # toolchain's so that the toolchain's Node stays first on PATH for everything else; only the installs use this one.
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: "24"
          package-manager-cache: false
      - id: corpus-node
        run: echo "dir=$(dirname "$(command -v node)")" >> "$GITHUB_OUTPUT"
      # RDT, react-docgen and the oracle run from apps/validate's dependencies.
      - uses: moonrepo/setup-toolchain@261c62cb5b0f580c7be7c8cd0f023a2e96756095 # v0.6.4
        with:
          auto-install: true
      - uses: orin-dx/actions/setup-pnpm-cache@2521888266780dabc7f5fd4c32b02d6ab82849db # v1.1
      - run: pnpm install --frozen-lockfile
      - run: cargo build --release --locked -p caliper-docgen
      # About 10 GB of installed node_modules is too large to cache; the package managers' stores are not.
      - uses: actions/cache@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        with:
          path: .corpora/caches
          key: weekly-${{ hashFiles('scripts/corpora.py', 'pnpm-lock.yaml') }}

def rate(pair):
    return pair[0] / pair[1] if pair[1] else 0.0


def oracle(binary, name, src, root, work):
    """How often TypeScript 7.1's checker contradicts Caliper's prop types (apps/validate/src/oracle.ts)."""
    caliper_json = os.path.join(work, f'{name}.caliper.json')
    with open(caliper_json, 'w') as f:
        subprocess.run([binary, 'extract', '--src', src, '--json', '--html-attributes', 'full', '--include-unexported',
                        '--load-dependencies', '--quiet'], stdout=f, check=True)
    list_file, tsconfig = program_inputs(name, src, work)
    verdicts = os.path.join(work, f'{name}.oracle.json')
    subprocess.run(['pnpm', '--dir', os.path.join(ROOT, 'apps', 'validate'), 'exec', 'tsx', 'src/oracle.ts', '--root', root,
                    '--src', src, '--tsconfig', tsconfig, '--caliper', caliper_json, '--out', verdicts, '--files',
                    list_file], check=True, timeout=3600)
    with open(verdicts) as f:
        e = json.load(f)
    shared = e['props_shared']
    return {'shared_props': shared, 'agree': rate((e['verdicts']['identical'] + e['verdicts']['spelled'], shared)),
            'wrong': rate((e['verdicts']['wrong'], shared))}

