import json
import subprocess

def run(*a):
    return subprocess.run(["/usr/bin/git", *a], capture_output=True, text=True)

prs = json.loads(subprocess.run(["gh", "pr", "list", "--state", "open", "--json", "number,headRefName"],
                                capture_output=True, text=True).stdout)
heads = {f"#{p['number']}": f"origin/{p['headRefName']}" for p in prs}
for ref in run("for-each-ref", "--format=%(refname:short)", "refs/remotes/origin/docs/").stdout.split():
